const entradas = $input.all();
const actualizaciones = [];

const limpiarTitulo = valor => String(valor ?? '')
  .replace(/[\r\n\t]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .toLocaleLowerCase('es');

const corregirTitulo = titulo => {
  const equivalencias = {
    'Recaudación Imp.\nde Sellos F':
      'Recaudación Imp.\r\nde Sellos F',

    'Recaudacion Reg. de Facil.\nde Pago\t':
      'Recaudacion Reg. de Facil.\r\nde Pago\t',

    'Recaudacion Imp. a los\nJuegos de Azar':
      'Recaudacion Imp. a los\r\nde Juegos de Azar'
  };

  return equivalencias[titulo] || titulo;
};

const totalesEsperados = {
  ipi: 48,
  cammesa: 9,
  ipc: 68,
  canasta: 22,
  sipa: 70,
  icc: 6
};

const perteneceAFuente = (titulo, fuente) => {
  const texto = limpiarTitulo(titulo);

  if (fuente === 'ipi') {
    return /^ipi\b/.test(texto) ||
      texto.includes('ipi divisiones');
  }

  if (fuente === 'ipc') {
    return /\bipc\b/.test(texto) ||
      texto.startsWith('indice de precios al consumidor');
  }

  if (fuente === 'canasta') {
    return /\bcba\b|\bcbt\b/.test(texto) ||
      texto.includes('canasta básica');
  }

  if (fuente === 'sipa') {
    return texto.includes('trabajo registrado') ||
      texto.includes('asalariados registrados') ||
      texto.includes('remuneración mediana') ||
      texto.includes('remuneración promedio');
  }

  if (fuente === 'cammesa') {
    return texto.includes('demanda (mwh)') ||
      texto.includes('categoría tarifa') ||
      texto.includes('categoria tarifa');
  }

  if (fuente === 'icc') {
    return texto.includes('confianza del consumidor');
  }

  return false;
};

for (let indice = 0; indice < entradas.length; indice++) {
  const buffer = await this.helpers.getBinaryDataBuffer(
    indice,
    'data'
  );

  const resumen = JSON.parse(
    buffer.toString('utf8').replace(/^\uFEFF/, '')
  );

  const cargasBase = (
    resumen.actualizaciones_google || []
  ).filter(item => item.hoja === 'BASE DE DATOS');

  const hayCargaGoogle = cargasBase.length > 0;
  const inicioSalida = actualizaciones.length;

  const titulosEnviados = cargasBase
    .flatMap(item => Object.keys(item.valores || {}))
    .filter(titulo =>
      limpiarTitulo(titulo) !== 'periodo' &&
      !String(titulo).startsWith('__')
    );

  const resultados = (
    resumen.resultados || []
  ).map(resultadoFuente => ({
    ...resultadoFuente,

    error_final: resultadoFuente.error_final || '',
    salida_final: resultadoFuente.salida_final || '',
    detalle: resultadoFuente.detalle || '',

    celdas_actualizadas: Number(
      resultadoFuente.celdas_actualizadas || 0
    ),

    cambios: Array.isArray(resultadoFuente.cambios)
      ? resultadoFuente.cambios
      : [],

    detalle_completo: Array.isArray(
      resultadoFuente.detalle_completo
    )
      ? resultadoFuente.detalle_completo
      : []
  }));

  const correctos = resultados.filter(
    resultado => resultado.estado === 'OK'
  );

  const cargas = [];

  for (const resultado of correctos) {
    const fuente = limpiarTitulo(resultado.fuente);

    const publicados = new Set(
      resultado.cambios.map(cambio =>
        limpiarTitulo(cambio.titulo || '')
      )
    );

    let titulos = cargasBase
      .filter(item =>
        !resultado.periodo ||
        String(item.periodo).slice(0, 7) ===
          String(resultado.periodo).slice(0, 7) ||
        String(item.periodo).toLowerCase() ===
          String(resultado.periodo).toLowerCase()
      )
      .flatMap(item => Object.keys(item.valores || {}))
      .filter(titulo =>
        publicados.has(limpiarTitulo(titulo))
      );

    if (!titulos.length) {
      titulos = titulosEnviados.filter(titulo =>
        perteneceAFuente(titulo, fuente)
      );
    }

    if (!titulos.length && correctos.length === 1) {
      titulos = titulosEnviados;
    }

    const enviadas = new Set(
      titulos.map(limpiarTitulo)
    ).size;

    if (!enviadas && !resultado.celdas_actualizadas) {
      continue;
    }

    cargas.push({
      fuente,
      nombre: resultado.nombre,
      periodo: resultado.periodo,

      columnas_enviadas: enviadas,

      columnas_esperadas: Number(
        totalesEsperados[fuente] ||
        resultado.detalle_completo.length ||
        enviadas
      ),

      celdas_actualizadas:
        resultado.celdas_actualizadas,

      columnas_faltantes: [],
      cambios: resultado.cambios
    });
  }

  if (!cargas.length && hayCargaGoogle) {
    const enviadas = new Set(
      titulosEnviados.map(limpiarTitulo)
    ).size;

    const unico = correctos.length === 1
      ? correctos[0]
      : null;

    const fuente = limpiarTitulo(
      unico?.fuente || 'varios'
    );

    cargas.push({
      fuente,

      nombre: unico?.nombre ||
        'Indicadores del Observatorio',

      periodo: unico?.periodo ||
        cargasBase[0]?.periodo,

      columnas_enviadas: enviadas,

      columnas_esperadas: Number(
        totalesEsperados[fuente] || enviadas
      ),

      celdas_actualizadas: Number(
        unico?.celdas_actualizadas || 0
      ),

      columnas_faltantes: [],
      cambios: unico?.cambios || []
    });
  }

  const aviso = {
    estado: resumen.estado,
    inicio: resumen.inicio,
    fin: resumen.fin,
    solicitadas: resumen.solicitadas,
    ejecutadas: resumen.ejecutadas,

    errores: resumen.errores || [],
    omitidas: resumen.omitidas || [],
    notificacion: resumen.notificacion || {},

    resultados,

    formato_sheet: resumen.formato_sheet || {},
    finalizacion: resumen.finalizacion || {},

    cargas
  };

  if (hayCargaGoogle) {
    // Comparar contra el Sheet aunque el Excel local
    // no haya cambiado.
    for (const item of cargasBase) {
      if (!item.periodo) {
        throw new Error(
          'La actualización no contiene el período correspondiente.'
        );
      }

      const valores = {};

      for (
        const [titulo, valor]
        of Object.entries(item.valores || {})
      ) {
        if (
          limpiarTitulo(titulo) === 'periodo' ||
          String(titulo).startsWith('__')
        ) {
          continue;
        }

        valores[corregirTitulo(titulo)] = valor;
      }

      if (!Object.keys(valores).length) {
        throw new Error(
          `La carga de ${item.periodo} no contiene columnas del indicador.`
        );
      }

      actualizaciones.push({
        json: {
          PERIODO: item.periodo,
          ...valores
        }
      });
    }
  } else {
    // Conservar el diagnóstico para Telegram cuando
    // no haya cargas preparadas.
    actualizaciones.push({
      json: {
        __solo_aviso: true
      }
    });
  }

  if (actualizaciones.length > inicioSalida) {
    const ultimo = actualizaciones[
      actualizaciones.length - 1
    ].json;

    ultimo.__enviar_aviso = true;
    ultimo.__aviso = aviso;
  }
}

return actualizaciones;

// carga Productivos — Python ya escribió y verificó en el Sheet.
// Este nodo solo pasa el aviso para Telegram.
const salida = [];
const entradas = $input.all();
for (let i = 0; i < entradas.length; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  const resumen = JSON.parse(buffer.toString('utf8').replace(/^\uFEFF/, ''));
  salida.push({
    json: {
      __solo_aviso: true,
      __enviar_aviso: true,
      __aviso: {
        estado: resumen.estado,
        inicio: resumen.inicio,
        fin: resumen.fin,
        errores: resumen.errores || [],
        notificacion: resumen.notificacion || {},
        resultados: resumen.resultados || []
      }
    }
  });
}
return salida;

// Preparar mensaje Telegram — el texto lo arma Python (scripts/comun/mensaje_telegram.py)
const items = $input.all().map(item => item.json || {});
const conAviso = items.find(item => item.__aviso) || {};
const aviso = conAviso.__aviso || {};
const texto = aviso.notificacion && aviso.notificacion.mensaje_telegram;

const errores = items
  .filter(item => item.error)
  .map(item => typeof item.error === 'string'
    ? item.error
    : (item.error.message || item.error.description || JSON.stringify(item.error)));

if (texto) {
  let mensaje = texto;
  if (errores.length) {
    mensaje += '\n\n❌ Error en n8n: ' + errores.join(' | ').slice(0, 400);
  }
  return [{ json: { mensaje } }];
}

const fecha = new Date().toLocaleString('es-AR', { timeZone: 'America/Asuncion' });
const mensaje = [
  '⚠️ REVISIÓN SIN RESUMEN',
  '',
  `Fecha: ${fecha}`,
  '',
  errores.length
    ? '❌ ' + errores.join(' | ').slice(0, 800)
    : 'El ejecutor de Python no entregó el aviso. Revisar salidas_n8n y los logs.'
].join('\n');
return [{ json: { mensaje } }];
